const crypto = require('crypto');
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const json      = items[i].json;
  const secret    = $env.CHATWOOT_WEBHOOK_SECRET;
  const received  = json.headers['x-chatwoot-signature'];
  const timestamp = json.headers['x-chatwoot-timestamp'];

  let ok = false, expected = null, rawLen = null, rawPreview = null, err = null;
  try {
    const rawBuf = await this.helpers.getBinaryDataBuffer(i, 'data');   // 'data' = nombre de la prop binaria
    rawLen = rawBuf.length;
    rawPreview = rawBuf.toString('utf8').slice(0, 60);

    const signed = Buffer.concat([Buffer.from(`${timestamp}.`), rawBuf]);
    expected = 'sha256=' + crypto.createHmac('sha256', secret).update(signed).digest('hex');

    ok = !!received
      && expected.length === received.length
      && crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(received));
  } catch (e) {
    err = String(e.message || e);
  }

  out.push({ json: { ...json, _hmac: { ok, expected, received, timestamp, rawLen, rawPreview, err } }, pairedItem: { item: i } });
}

return out;

// === DECIDIR — decide QUÉ hacer y arma la conversación (sin catálogo: eso lo inyecta 'Armar mensajes') ===
const webhookData = $('Chatwoot Webhook').first().json;
const body = webhookData.body;
const myMessageId = body.id;
const conversationId = body.conversation.id;
const accountId = body.account.id;

// F5: created_at robusto (unix int, string numérico o ISO) → siempre número
const num = (v) => {
  if (v == null) return 0;
  if (typeof v === 'number') return v;
  const n = Number(v);
  if (Number.isFinite(n)) return n;
  const t = Date.parse(v);
  return Number.isFinite(t) ? t : 0;
};
const myCreatedAt = num(body.created_at);

const historialJson = $('Get Historial').first().json;
const rawPayload = historialJson.payload;
const allMessages = Array.isArray(rawPayload) ? rawPayload : (rawPayload && rawPayload.messages ? rawPayload.messages : []);

const isIn = (m) => m.message_type === 'incoming' || m.message_type === 0;
const isOut = (m) => (m.message_type === 'outgoing' || m.message_type === 1) && !m.private;
const hasContent = (m) => m.content && String(m.content).trim().length > 0;

const sorted = allMessages.slice().sort((a, b) => num(a.created_at) - num(b.created_at));

// DEBOUNCE (F1): el "último" es el último ENTRANTE CON TEXTO.
// Una foto que llega después de la pregunta ya no gana el "soy el último".
const incoming = sorted.filter((m) => isIn(m) && hasContent(m));
const lastIncoming = incoming.length ? incoming[incoming.length - 1] : null;
if (lastIncoming && myMessageId && lastIncoming.id !== myMessageId) {
  return [{ json: { action: 'skip', reason: 'no-soy-el-ultimo', conversationId, accountId } }];
}

// IDEMPOTENCIA (F5): ya hay respuesta posterior a mi mensaje → no repito
const repliedAfter = sorted.some((m) => isOut(m) && num(m.created_at) > myCreatedAt);
if (repliedAfter) {
  return [{ json: { action: 'skip', reason: 'ya-respondido', conversationId, accountId } }];
}

// Ráfaga del cliente = entrantes con texto desde la última salida
let lastOutIdx = -1;
for (let i = sorted.length - 1; i >= 0; i--) {
  if (isOut(sorted[i])) { lastOutIdx = i; break; }
}
const burst = sorted.slice(lastOutIdx + 1).filter((m) => isIn(m) && hasContent(m)).map((m) => m.content);
// v8.1 NFC: ningun lado normaliza Unicode. Un teclado iOS/macOS que emita acentos
// DESCOMPUESTOS ("impresio\u0301n") hace fallar todo match con acento, en silencio y
// solo para algunos clientes. El catalogo esta en NFC; el mensaje del cliente, no.
const mergedUser = burst.join('\n').normalize('NFC');

if (!mergedUser) {
  return [{ json: { action: 'skip', reason: 'sin-texto-nuevo', conversationId, accountId } }];
}

// INJECTION: regex sobre el texto agregado (red barata; Tier-1 lo duplicará)
const INJECTION_PATTERNS = [
  /ignor[aá].*(instrucciones|reglas|rol)/i,
  /olvid[aá].*(instrucciones|reglas|rol)/i,
  /nuevo rol/i,
  /ignore (previous|instructions|your)/i,
  /system prompt/i,
  /jailbreak/i,
  /\bDAN\b/,
  /pretend you are/i,
  /do anything now/i,
  /forget your instructions/i
];
if (INJECTION_PATTERNS.some((p) => p.test(mergedUser))) {
  return [{ json: { action: 'injection', conversationId, accountId } }];
}

// PRIMER MENSAJE (F3): saludo enlatado SOLO si el texto es un saludo puro.
// Primer mensaje con pregunta → process (lo contesta el LLM).
const hasOutgoing = sorted.some(isOut);
function isGreetingOnly(text) {
  const t = (text || '')
    .toLowerCase()
    .replace(/[¡!¿?.,;:()"']/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!t) return false;
  const G = '(hola|holis|buenas|buen dia|buen día|buenos dias|buenos días|buenas tardes|buenas noches|hey|que tal|qué tal|como andas|cómo andás|como va|cómo va|todo bien)';
  const re = new RegExp('^' + G + '( ' + G + ')*$');
  return re.test(t);
}
if (!hasOutgoing && isGreetingOnly(mergedUser)) {
  return [{ json: { action: 'primer-mensaje', conversationId, accountId } }];
}

// CAP DE RESPUESTAS POR CONVERSACIÓN (ventana rodante 24h): tope duro para floods sostenidos.
const CAP_RESPUESTAS = 25;
const nowMs = Date.now();
const botOut = sorted.filter((m) => isOut(m) && hasContent(m));
const botOut24 = botOut.filter((m) => nowMs - num(m.created_at) < 86400000);
const CAP_MARK = 'muchos mensajes en esta conversación';
if (botOut24.length >= CAP_RESPUESTAS) {
  const capYaAvisado = botOut24.some((m) => String(m.content).toLowerCase().includes(CAP_MARK));
  if (capYaAvisado) {
    return [{ json: { action: 'skip', reason: 'cap-ya-avisado', conversationId, accountId } }];
  }
  return [{ json: { action: 'cap', conversationId, accountId } }];
}

// PROCESS: armar la conversación (sin system, sin catálogo). 'Armar mensajes' le prepende el system+catálogo.
// ¿ya se le avisó al cliente que el canal es solo informativo? (buscamos el email del negocio en salientes del bot)
const avisoDado = sorted.some((m) => isOut(m) && hasContent(m) && String(m.content).toLowerCase().includes('terminalgrafica@gmail.com'));
// Últimas 3 respuestas del bot → el LLM las usa para no repetirse (action noop)
const lastBotReplies = botOut.slice(-3).map((m) => String(m.content));

const conversation = [];
const history = sorted.slice(0, lastOutIdx + 1).slice(-6);
for (const m of history) {
  if (isIn(m) && hasContent(m)) {
    conversation.push({ role: 'user', content: m.content });
  } else if (isOut(m) && hasContent(m)) {
    conversation.push({ role: 'assistant', content: m.content });
  }
}
conversation.push({ role: 'user', content: mergedUser });

return [{ json: { action: 'process', conversation, userMessage: mergedUser, avisoDado, lastBotReplies, conversationId, accountId } }];

// Rama Fail del Guardrails Tier-2. Distingue una VIOLACIÓN REAL (jailbreak/topical
// flaggeado por el modelo) de una CAÍDA del modelo-guard (executionFailed) o un item
// de error del nodo. Fail-open ante caída: no penaliza, deja seguir al LLM principal
// (que ya degrada a handoff si OpenRouter está caído).
const j = $input.first().json;
const checks = Array.isArray(j.checks) ? j.checks : [];
const violated = checks.filter((c) => c && c.triggered && !c.executionFailed);
const realViolation = violated.length > 0;
// reason = nombre del guard que disparó (jailbreak | topicalAlignment)
const reason = realViolation ? String(violated[0].name || 'tier2') : 'model_error';

const b = $('Chatwoot Webhook').first().json.body;
const sid = b.sender?.id ?? b.conversation?.meta?.sender?.id ?? '';
const decidir = $('Decidir').first().json;

return [{
  json: {
    realViolation,
    reason,
    senderKey: String(sid),
    conversationId: decidir.conversationId,
    accountId: decidir.accountId,
    userMessage: decidir.userMessage,
  },
  pairedItem: { item: 0 },
}];

// v8.3 EXTRAER PALABRAS — puente determinístico entre el LLM 1 y la búsqueda.
// NO es una llamada nueva: reusa el string que el LLM ya emite en `producto` y lo
// mezcla con las palabras del propio cliente. La búsqueda pondera por rareza, así
// que sumar palabras del cliente NO ensucia: un token genérico pesa ~1 y uno raro
// ~3,8, y el corte es relativo al mejor score.
const parsear = $('Leer Selector').first().json;
const decidir = $('Decidir').first().json;
const p = parsear.precio || {};
// v9.3: la accion 'opciones' no llena `precio` — sus nombres (hasta 4, ya
// copiados del catalogo por el LLM) viven en `opciones.productos`. Se los suma
// como pista igual que al `producto` de la rama precio.
const nombresOpciones = ((parsear.opciones || {}).productos || []).filter(Boolean);

// Ventana de mensajes del cliente: la usa el guard de nicho del SQL (el cliente pudo
// decir "medicina" dos mensajes atrás y el guard tiene que verlo igual).
const msgsCliente = (Array.isArray(decidir.conversation) ? decidir.conversation : [])
  .filter((m) => m && m.role === 'user').map((m) => String(m.content || ''));
const ventana = (msgsCliente.join(' ') || String(decidir.userMessage || '')).normalize('NFC');

// STOPWORDS: palabras de pedido que no discriminan NADA en un catálogo de imprenta.
// Ojo con la línea: acá NO van sustantivos de producto ('hoja', 'papel', 'cartel')
// aunque sean frecuentes — de esos se encarga el IDF, que los pondera bajo sin
// perderlos. Sacarlos a mano rompería "papel kraft" (kraft solo, sin papel, matchea
// menos). Sólo salen las que no nombran nada.
const STOP = new Set(['que','como','para','por','con','sin','una','uno','unos','unas',
  'del','las','los','mas','muy','pero','este','esta','esto','ese','esa','eso','tiene',
  'tienen','hacen','haces','hace','puedo','quiero','queria','necesito','necesitaria',
  'cuanto','cuanta','cuantos','cuantas','sale','salen','vale','valen','cuesta','cuestan',
  'precio','precios','presupuesto','cotizacion','cotizar','hola','buenas','gracias',
  'porfa','favor','decime','pasame','mandame','saber','consulta','consultar','tengo',
  'seria','serian','estan','esta','son','ser','hay','algo','todo','toda','y','o','de',
  'el','la','lo','en','a','al','un','mi','me','te','se','su','es','si','no']);

const norm = (s) => String(s || '').normalize('NFC').toLowerCase()
  .replace(/[áéíóúü]/g, (c) => ({ 'á': 'a', 'é': 'e', 'í': 'i', 'ó': 'o', 'ú': 'u', 'ü': 'u' }[c]))
  .replace(/ñ/g, 'n');

// NÚMEROS PUROS FUERA (medido en la 1ª corrida real, 2026-07-27): "imprimir 100
// hojas" mandaba el token `100` a la búsqueda, y como está en 4 productos su IDF es
// alto (3,09) — así que "100 Tarjetas", "1000 Tarjetas" y "Talonarios Rifas 100
// numeros" se metían en el top-8 de una consulta de impresiones. La cantidad NO es
// un sustantivo de producto: es la misma clase de bug que la regla de sustantivo de
// v8 ("anillado para 120 hojas" no son 120 anillados).
// Los gramajes SÍ se conservan: van pegados a su unidad ("80gr") o los aporta el
// LLM en el nombre del producto, y ahí discriminan de verdad.
// Los packs no se pierden: se siguen encontrando por "tarjetas".
const tokenizar = (txt) => norm(txt).replace(/[^a-z0-9]+/g, ' ').split(' ')
  .filter((t) => t && !STOP.has(t) && !/^\d+$/.test(t)
    && (t.length >= 3 || /^(a[0-5]|opp|uv|pvc)$/.test(t)));

// Fuente 1: lo que el LLM eligió como producto y variante. Es su mejor aporte —
// acierta el sustantivo — y acá deja de ser una elección para pasar a ser una pista.
// Fuente 2: el mensaje del cliente, que trae los ejes que el LLM suele omitir.
const delLlm = tokenizar((p.producto || '') + ' ' + (p.variante || '') + ' ' + nombresOpciones.join(' '));
const delCliente = tokenizar(decidir.userMessage || '');

// Orden: primero las del LLM (más señal), después las del cliente que no estén ya.
// Dedupe conservando orden. Cap de 12 para que un mensaje larguísimo no dispare un
// SQL con 40 tokens (el IDF los pondera, pero el LIKE por token cuesta).
const vistas = new Set();
const palabras = [];
for (const t of delLlm.concat(delCliente)) {
  if (vistas.has(t)) continue;
  vistas.add(t); palabras.push(t);
  if (palabras.length >= 12) break;
}

// CUPO: cuántos candidatos ve el cliente. Decisión de Martin (2026-07-27): el bot
// NUNCA repregunta para desambiguar, muestra todo de una — el mensaje de WhatsApp es
// el costo dominante y listar N opciones ahorra los turnos que la repregunta gasta.
// Por eso 8 y no 4: el cupo dejó de ser "cuánto tolera el LLM" y pasó a ser "cuánto
// entra en un mensaje legible" (el compositor comprime la lista en prosa).
const CUPO = 8;

return [{
  json: {
    ...parsear,
    palabras: palabras.join(' '),
    ventana,
    cupo: CUPO,
    // Telemetría: sin esto no hay forma de saber si una resolución mala fue culpa
    // de la búsqueda (trajo mal) o del filtro (eligió mal de una lista buena).
    _busqueda: { delLlm, delCliente, usadas: palabras },
  },
  pairedItem: { item: 0 },
}];

